package com.portfolio.cms.service;
import com.portfolio.cms.dto.ContactRequest; import lombok.RequiredArgsConstructor; import org.springframework.beans.factory.annotation.Value; import org.springframework.mail.SimpleMailMessage; import org.springframework.mail.javamail.JavaMailSender; import org.springframework.scheduling.annotation.Async; import org.springframework.stereotype.Service;
@Service @RequiredArgsConstructor public class EmailService { private final JavaMailSender sender; @Value("${app.contact.email-to:}") String to; @Value("${spring.mail.host:}") String host; @Async public void send(ContactRequest r){if(to==null||to.isBlank()||host==null||host.isBlank()||"localhost".equals(host)) return; SimpleMailMessage m=new SimpleMailMessage();m.setTo(to);m.setReplyTo(r.email());m.setSubject("Portfolio contact: "+(r.subject()==null?"New message":r.subject()));m.setText("Name: "+r.name()+"\nEmail: "+r.email()+"\n\n"+r.message());sender.send(m);} }
